// -----------------------------------------------------------------------------
// File: rtlnet_ddr_amd.sv
// Purpose: the AMD 7-series implementation of the RTLNet DDR3 core: the MIG
//   controller IP rtlnet_ddr_mig (generated by ip/rtlnet_ddr_mig.tcl) behind
//   the neutral port list of rtlnet_ddr.
// Overview:
//   * One instance of rtlnet_ddr_mig, "No Buffer" clocking: sys_clk (100 MHz)
//     and ref_clk (200 MHz) arrive already buffered from the board top; MIG
//     builds its own PLL/MMCM from sys_clk and returns ui_clk (100 MHz).
//   * ui_resetn is the MIG ui reset (ui_clk_sync_rst, high while the MIG clock
//     tree is not locked or sys_rstn is low) inverted; s_axi_aresetn is the
//     reset the MIG AXI slave runs with, driven by the board top.
//   * Unused MIG services are tied inactive: self refresh, user refresh and ZQ
//     requests; the temperature, spare UI clocks and acknowledge outputs are not
//     connected. (The calibration tap loader ports exist only when the IP is built
//     with SKIP_CALIB, which the build does not define.)
//   * AXI4 data width 128 bits (MIG native: 16 DQ x 8 beats), address 29 bits
//     (512 MiB), ID width 2; the burst rules of the controller (INCR, full
//     width, no 4 KiB crossing) are enforced by rtlnet_axi_arbiter in front.
//   * The only AMD-specific file of the core besides the IP script.
// Language: SystemVerilog-2012.
// Revision: 11-09-2026
//   * 11-09-2026: initial version.
// Clocks: sys_clk and ref_clk (inputs to the controller PLL, asynchronous to
//   each other as far as this file is concerned); ui_clk (controller user
//   clock, 100 MHz) for every AXI4 port and status output.
// -----------------------------------------------------------------------------
module rtlnet_ddr_amd #(
  parameter int ADDR_W = 29,
  parameter int DATA_W = 128,
  parameter int ID_W   = 2
)(
  // Controller clocks and reset: sys_clk 100 MHz (controller PLL input),
  // ref_clk 200 MHz (IDELAYCTRL reference), sys_rstn asynchronous active low.
  input  logic                sys_clk,
  input  logic                ref_clk,
  input  logic                sys_rstn,

  // User clock and its reset (ui_clk domain, reset = MIG ui reset, active
  // low), calibration status.
  output logic                ui_clk,
  output logic                ui_resetn,
  input  logic                s_axi_aresetn,
  output logic                init_calib_complete,

  // AXI4 slave, ui_clk domain.
  input  logic [ID_W-1:0]     s_axi_awid,
  input  logic [ADDR_W-1:0]   s_axi_awaddr,
  input  logic [7:0]          s_axi_awlen,
  input  logic [2:0]          s_axi_awsize,
  input  logic [1:0]          s_axi_awburst,
  input  logic                s_axi_awlock,
  input  logic [3:0]          s_axi_awcache,
  input  logic [2:0]          s_axi_awprot,
  input  logic [3:0]          s_axi_awqos,
  input  logic                s_axi_awvalid,
  output logic                s_axi_awready,
  input  logic [DATA_W-1:0]   s_axi_wdata,
  input  logic [DATA_W/8-1:0] s_axi_wstrb,
  input  logic                s_axi_wlast,
  input  logic                s_axi_wvalid,
  output logic                s_axi_wready,
  output logic [ID_W-1:0]     s_axi_bid,
  output logic [1:0]          s_axi_bresp,
  output logic                s_axi_bvalid,
  input  logic                s_axi_bready,
  input  logic [ID_W-1:0]     s_axi_arid,
  input  logic [ADDR_W-1:0]   s_axi_araddr,
  input  logic [7:0]          s_axi_arlen,
  input  logic [2:0]          s_axi_arsize,
  input  logic [1:0]          s_axi_arburst,
  input  logic                s_axi_arlock,
  input  logic [3:0]          s_axi_arcache,
  input  logic [2:0]          s_axi_arprot,
  input  logic [3:0]          s_axi_arqos,
  input  logic                s_axi_arvalid,
  output logic                s_axi_arready,
  output logic [ID_W-1:0]     s_axi_rid,
  output logic [DATA_W-1:0]   s_axi_rdata,
  output logic [1:0]          s_axi_rresp,
  output logic                s_axi_rlast,
  output logic                s_axi_rvalid,
  input  logic                s_axi_rready,

  // DDR3 SDRAM pins (MT41K256M16, 16 bit, one rank).
  inout  wire  [15:0]         ddr3_dq,
  inout  wire  [1:0]          ddr3_dqs_n,
  inout  wire  [1:0]          ddr3_dqs_p,
  output logic [14:0]         ddr3_addr,
  output logic [2:0]          ddr3_ba,
  output logic                ddr3_ras_n,
  output logic                ddr3_cas_n,
  output logic                ddr3_we_n,
  output logic                ddr3_reset_n,
  output logic [0:0]          ddr3_ck_p,
  output logic [0:0]          ddr3_ck_n,
  output logic [0:0]          ddr3_cke,
  output logic [1:0]          ddr3_dm,
  output logic [0:0]          ddr3_odt
);

  logic ui_rst;

  generate
    if (ADDR_W != 29 || DATA_W != 128 || ID_W != 2) begin : g_bad_cfg
      $fatal(1, "rtlnet_ddr_amd: ADDR_W=%0d DATA_W=%0d ID_W=%0d, the MIG project is 29/128/2", ADDR_W, DATA_W, ID_W);
    end
  endgenerate

  assign ui_resetn = ~ui_rst;

  // MIG controller (generated from ip/rtlnet_ddr_mig.prj).
  rtlnet_ddr_mig u_mig (
    .ddr3_addr           (ddr3_addr),
    .ddr3_ba             (ddr3_ba),
    .ddr3_cas_n          (ddr3_cas_n),
    .ddr3_ck_n           (ddr3_ck_n),
    .ddr3_ck_p           (ddr3_ck_p),
    .ddr3_cke            (ddr3_cke),
    .ddr3_ras_n          (ddr3_ras_n),
    .ddr3_reset_n        (ddr3_reset_n),
    .ddr3_we_n           (ddr3_we_n),
    .ddr3_dq             (ddr3_dq),
    .ddr3_dqs_n          (ddr3_dqs_n),
    .ddr3_dqs_p          (ddr3_dqs_p),
    .init_calib_complete (init_calib_complete),
    .ddr3_dm             (ddr3_dm),
    .ddr3_odt            (ddr3_odt),
    .ui_clk              (ui_clk),
    .ui_clk_sync_rst     (ui_rst),
    .ui_addn_clk_0       (),
    .ui_addn_clk_1       (),
    .ui_addn_clk_2       (),
    .ui_addn_clk_3       (),
    .ui_addn_clk_4       (),
    .mmcm_locked         (),
    .aresetn             (s_axi_aresetn),
    .app_sr_req          (1'b0),
    .app_ref_req         (1'b0),
    .app_zq_req          (1'b0),
    .app_sr_active       (),
    .app_ref_ack         (),
    .app_zq_ack          (),
    .s_axi_awid          (s_axi_awid),
    .s_axi_awaddr        (s_axi_awaddr),
    .s_axi_awlen         (s_axi_awlen),
    .s_axi_awsize        (s_axi_awsize),
    .s_axi_awburst       (s_axi_awburst),
    .s_axi_awlock        (s_axi_awlock),
    .s_axi_awcache       (s_axi_awcache),
    .s_axi_awprot        (s_axi_awprot),
    .s_axi_awqos         (s_axi_awqos),
    .s_axi_awvalid       (s_axi_awvalid),
    .s_axi_awready       (s_axi_awready),
    .s_axi_wdata         (s_axi_wdata),
    .s_axi_wstrb         (s_axi_wstrb),
    .s_axi_wlast         (s_axi_wlast),
    .s_axi_wvalid        (s_axi_wvalid),
    .s_axi_wready        (s_axi_wready),
    .s_axi_bid           (s_axi_bid),
    .s_axi_bresp         (s_axi_bresp),
    .s_axi_bvalid        (s_axi_bvalid),
    .s_axi_bready        (s_axi_bready),
    .s_axi_arid          (s_axi_arid),
    .s_axi_araddr        (s_axi_araddr),
    .s_axi_arlen         (s_axi_arlen),
    .s_axi_arsize        (s_axi_arsize),
    .s_axi_arburst       (s_axi_arburst),
    .s_axi_arlock        (s_axi_arlock),
    .s_axi_arcache       (s_axi_arcache),
    .s_axi_arprot        (s_axi_arprot),
    .s_axi_arqos         (s_axi_arqos),
    .s_axi_arvalid       (s_axi_arvalid),
    .s_axi_arready       (s_axi_arready),
    .s_axi_rid           (s_axi_rid),
    .s_axi_rdata         (s_axi_rdata),
    .s_axi_rresp         (s_axi_rresp),
    .s_axi_rlast         (s_axi_rlast),
    .s_axi_rvalid        (s_axi_rvalid),
    .s_axi_rready        (s_axi_rready),
    .device_temp         (),
    .sys_clk_i           (sys_clk),
    .clk_ref_i           (ref_clk),
    .sys_rst             (sys_rstn)
  );

endmodule
